/**
 * Bài 25 — N4 総復習 (Ôn tập & THI THỬ JLPT N4) · TIẾP SAU SÁCH, cấp N4 (xem ../SOAN-BAI.md mục 8 phần D).
 * Bài CUỐI chặng 21–25 và cuối cả cấp N4 ⇒ KHÔNG có mục A–C (hội thoại, từ vựng, buổi học, luyện thêm) mà thay bằng
 * ĐỀ THI THỬ đúng cấu trúc đề JLPT N4 hiện hành + ôn tổng hợp cả cấp:
 *   1. b25-thi-thu-gioi-thieu      — cấu trúc đề N4 (3 phần · 25′ / 55′ / 35′), thang 180, điểm đạt 90, điểm liệt 38/19, mẹo, bảng điểm.
 *   2. b25-thi-thu-1-moji-goi      — Đề 1 · 言語知識（文字・語彙）: 問題1 漢字読み 7 · 問題2 表記 5 · 問題3 文脈規定 8 · 問題4 言い換え類義 4 · 問題5 用法 4 = 28.
 *   3. b25-thi-thu-2-bunpo-dokkai  — Đề 1 · 言語知識（文法）・読解: 文法形式 13 · 文の組み立て 4 · 文章の文法 4 · 短文 3 · 中文 3 · 情報検索 2 = 29.
 *   4. b25-thi-thu-3-choukai       — Đề 1 · 聴解: 課題理解 8 · ポイント理解 7 · 発話表現 5 · 即時応答 8 = 28.  (Đề 1 tổng 85 câu.)
 *   5. b25-thi-thu-bang-diem       — quy đổi câu đúng → điểm, điểm liệt, bảng "sai câu nào ôn Bài nào / mẫu nào" (Bài 8–24).
 *   6. b25-on-tap-ngu-phap         — tổng ôn MỌI mẫu ngữ pháp N4 đã học (sách Bài 8–15 + Bài 16–24) + bảng các cặp hay nhầm + 45 câu.
 *   7. b25-on-tap-tu-vung-han-tu   — chữ Hán của lớp Bài 8–15 + chữ mới Bài 16–24, từ trọng tâm theo chủ đề + 66 câu + đọc chữ.
 *   8. b25-de-2                    — Đề thi thử số 2 rút gọn (61 câu đủ 3 phần) để thi lại sau khi ôn.
 * Người học đã xong Bài 1–15 (ポイント 1–124) và Bài 16–24 (thể khả năng, ý chí, つもり · ば, なら, し, すぎる, やすい · cho – nhận
 * hành động, ておく, てある · てしまう, てみる, ところ, のに · そう, ようだ, らしい, かもしれない, はず · ために, ように, ようになる・
 * する, ことにする・なる · bị động, ばかり · sai khiến, mệnh lệnh, ように言う · kính ngữ, かどうか). Đề CHỈ dùng từ / ngữ pháp / chữ
 * Hán đã học tới Bài 24; chữ Hán được hỏi trong 漢字読み・表記 lấy từ chữ của lớp Bài 8–15 + chữ mới Bài 16–24.
 * Đề, bài đọc, kịch bản nghe: VIẾT MỚI 100%, không chép đề JLPT thật hay sách luyện thi nào.
 *
 * Nhân vật (giới tính quyết định giọng đọc, theo sách p.14): nữ = パク, ワン, アンナ, メアリー, マリヤム, 山口, 木村, リン, 鈴木 ·
 * nam = マルコ, ダニエル, ナタポン, カルロス, 西川, 本田先生, 小林店長.
 * Người phụ (không tên riêng / chỉ nói trong bài nghe): ナレーター (người dẫn đề nghe) — ja-nu · {医者|いしゃ} (nghe 60) — nữ, ja-nu ·
 * {駅員|えきいん} (nghe 61) — nam, ja-nam · {駅員|えきいん} (nghe 64) — nữ, ja-nu · {会社|かいしゃ}の{人|ひと} (nghe 69) — nữ, ja-nu ·
 * {大家|おおや}さん (đề 2 nghe 44) — nam, ja-nam · {会社|かいしゃ}の{人|ひと} (đề 2 nghe 46) — nam, ja-nam · お{巡|まわ}りさん (đề 2 nghe 48) — nam, ja-nam.
 * {森|もり} — trưởng phòng (nhắc tên trong câu hỏi/bài nghe, không nói).
 * Nghe: 'ja-nu' = nữ, 'ja-nam' = nam (bộ kiểm chỉ nhận hai giọng này).
 */
import type { Block, Lesson } from '@/components/sach-hoc/types';

type Item = { q: string; options: string[]; correct: number; why: string };
const Q = (q: string, options: string[], correct: number, why: string): Item => ({ q, options, correct, why });
/** Đáp án đúng `dung` đặt vào vị trí `pos` giữa các đáp án nhiễu `sai` — để rải đều A/B/C/D mà không đếm tay. */
const QP = (q: string, dung: string, sai: string[], pos: number, why: string): Item =>
  Q(q, [...sai.slice(0, pos), dung, ...sai.slice(pos)], pos, why);

type LL = [who: string, voice: 'ja-nu' | 'ja-nam', text: string, ro: string, vi: string];
const NG = (id: string, title: string, note: string, lines: LL[]): Block => ({
  t: 'listen',
  id,
  title,
  note,
  lines: lines.map(([who, voice, text, ro, vi]) => ({ who, voice, text, ro, vi })),
});
const NA = 'ナレーター';

